DROP TABLE IF EXISTS `detection_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `detection_records` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `record_type` enum('single','batch','camera') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检测类型：单张/批量/摄像头',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检测文件名称',
  `file_size` int DEFAULT NULL COMMENT '文件大小（字节）',
  `original_image_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原图URL/路径',
  `result_image_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检测结果图URL/路径',
  `mask_image_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '掩码图URL/路径',
  `wastage_rate` decimal(5,2) DEFAULT NULL COMMENT '浪费率（%）',
